#include <stdio.h>
#include <string.h>
int main(void)
{
  char s[81], t[81];
  int i, n;
  scanf("%s", s);
  n = strlen(s);
  for (i = 0; i < n; i++)
    t[i] = s[n - 1 - i];
  t[n] = '\0';
  printf("%s\n", t);
  return 0;
}
